// Initialize or increment page counter
const existingPage = $('Check Next Page')?.first()?.json?.nextPage;
const page = existingPage || 1;

return [{ json: { page, per_page: 50 } }];

const response = $input.first().json;
const posts = response.body;
const headers = response.headers || {};
const totalPages = parseInt(headers['x-wp-totalpages'] || '1');
const currentPage = parseInt($('Set Page').first().json.page);
const hasNextPage = currentPage < totalPages;

const results = [];

for (const post of posts) {
  let title = post.title.rendered
    .replace(/<[^>]+>/g, '')
    .replace(/&#8217;/g, "'")
    .replace(/&#8211;/g, "-")
    .replace(/&amp;/g, "&")
    .replace(/&rsquo;/g, "'")
    .replace(/&nbsp;/g, " ")
    .replace(/&rdquo;/g, '"')
    .replace(/&ldquo;/g, '"');

  const date = post.date.substring(0, 10);

  let text = post.content.rendered;
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
  text = text.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  text = text.replace(/\.[\w-][\s\S]*?\{[\s\S]*?\}/g, '');
  text = text.replace(/<h[1-6][^>]*>(.*?)<\/h[1-6]>/gs, '\n\n$1\n\n');
  text = text.replace(/<p[^>]*>(.*?)<\/p>/gs, '$1\n\n');
  text = text.replace(/<br\s*\/?>/g, '\n');
  text = text.replace(/<li[^>]*>(.*?)<\/li>/gs, '  - $1\n');
  text = text.replace(/<a[^>]*>(.*?)<\/a>/gs, '$1');
  text = text.replace(/<[^>]+>/g, '');
  text = text.replace(/&#(\d+);/g, (m, n) => String.fromCharCode(n));
  text = text.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&rsquo;/g, "'").replace(/&nbsp;/g, ' ');
  text = text.replace(/\n{3,}/g, '\n\n').trim();

  const header = `Source: ${post.link}\nDate: ${date}\n\n${title}\n${'='.repeat(Math.min(title.length, 60))}\n\n`;
  const searchTerm = `${date} - ${title.substring(0, 30).replace(/'/g, "")}`;

  results.push({
    json: {
      title,
      date,
      searchQuery: `name contains '${searchTerm}' and mimeType = 'application/vnd.google-apps.document' and trashed = false`,
      fullText: header + text,
      hasNextPage,
      nextPage: currentPage + 1
    }
  });
}

return results;

const items = $input.all();
const parseItems = $('Parse All Posts').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const files = items[i].json.files || [];
  if (files.length === 0) continue;

  results.push({
    json: {
      docId: files[0].id,
      docName: files[0].name,
      title: parseItems[i].json.title,
      fullText: parseItems[i].json.fullText,
      hasNextPage: parseItems[i].json.hasNextPage,
      nextPage: parseItems[i].json.nextPage
    }
  });
}

return results.length > 0 ? results : [{ json: { skip: true, hasNextPage: parseItems[0]?.json?.hasNextPage || false, nextPage: parseItems[0]?.json?.nextPage || 1 } }];

const items = $input.all();
const matchItems = $('Match + Filter Found').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const content = items[i].json.content || '';
  if (content.trim().length < 10) {
    results.push({
      json: {
        docId: matchItems[i].json.docId,
        title: matchItems[i].json.title,
        fullText: matchItems[i].json.fullText,
        hasNextPage: matchItems[i].json.hasNextPage,
        nextPage: matchItems[i].json.nextPage
      }
    });
  }
}

return results.length > 0 ? results : [{ json: { skip: true, hasNextPage: matchItems[0]?.json?.hasNextPage || false, nextPage: matchItems[0]?.json?.nextPage || 1 } }];

// Check if there are more pages to process
const items = $input.all();
let hasNextPage = false;
let nextPage = 1;

for (const item of items) {
  if (item.json.hasNextPage) {
    hasNextPage = true;
    nextPage = item.json.nextPage;
    break;
  }
}

if (hasNextPage) {
  return [{ json: { nextPage, continueLoop: true } }];
} else {
  return [{ json: { continueLoop: false, message: 'All pages processed' } }];
}

// Wait 3 seconds between pages to avoid rate limits
await new Promise(resolve => setTimeout(resolve, 3000));
return $input.all();
